"""Regenerate js/device-llm-catalog.js and vendor/mediapipe-genai-<version>/: the pinned files of the on-device AI (js/device-llm.js).

    python3 tools/device_llm_catalog.py                     # downloads the model (2 GB) and the engine, hashes them
    python3 tools/device_llm_catalog.py --model FILE        # the same model already on disk (must be the pinned revision)

Needs the network. The app never chooses a file itself: the model (Gemma 4 E2B for the web, Apache-2.0, Hugging Face, pinned to
a commit) and the engine binary (MediaPipe LLM Inference, @mediapipe/tasks-genai on npm, Apache-2.0) are fetched through
/api/device-llm, and every 64 MiB part of the model and the engine binary are checked against the SHA-256 written here. The
small engine files the page loads as scripts (the ES module and the wasm loader) go into vendor/, inside the app shell.
"""
import argparse, hashlib, json, urllib.request
from pathlib import Path

root = Path(__file__).resolve().parents[1]
GENAI_VERSION = '0.10.29'
NPM = f'https://cdn.jsdelivr.net/npm/@mediapipe/tasks-genai@{GENAI_VERSION}/'
MODEL_REPO = 'litert-community/gemma-4-E2B-it-litert-lm'
MODEL_COMMIT = 'a790a852d433991c0c0a41c1154cf9b3850300fa'
MODEL_FILE = 'gemma-4-E2B-it-web.task'
PART = 64 * 1024 * 1024


def get(url):
    with urllib.request.urlopen(urllib.request.Request(url, headers={'user-agent': 'ai-ebook-reader-catalog'}), timeout=600) as r:
        return r.read()


def model_parts(path):
    parts = []
    with open(path, 'rb') as f:
        while chunk := f.read(PART):
            parts.append(hashlib.sha256(chunk).hexdigest())
    return parts


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument('--model', help='the model file already downloaded')
    args = ap.parse_args()
    model_url = f'https://huggingface.co/{MODEL_REPO}/resolve/{MODEL_COMMIT}/{MODEL_FILE}'
    path = Path(args.model) if args.model else None
    if not path:
        path = root / '.device-llm-model.tmp'
        path.write_bytes(get(model_url))
    size = path.stat().st_size
    parts = model_parts(path)
    if not args.model:
        path.unlink()

    vendor = root / f'vendor/mediapipe-genai-{GENAI_VERSION}'
    vendor.mkdir(parents=True, exist_ok=True)
    for name in ('genai_bundle.mjs', 'wasm/genai_wasm_internal.js'):
        (vendor / Path(name).name).write_bytes(get(NPM + name).replace(b'//# sourceMappingURL=genai_bundle_mjs.js.map', b''))
    (vendor / 'LICENSE.md').write_text(
        f'@mediapipe/tasks-genai {GENAI_VERSION} (https://www.npmjs.com/package/@mediapipe/tasks-genai), Apache License 2.0,\n'
        'Copyright The MediaPipe Authors. https://www.apache.org/licenses/LICENSE-2.0\n', encoding='utf-8')
    wasm = get(NPM + 'wasm/genai_wasm_internal.wasm')

    catalog = {
        'engine': {'version': GENAI_VERSION, 'module': f'vendor/mediapipe-genai-{GENAI_VERSION}/genai_bundle.mjs',
                   'loader': f'vendor/mediapipe-genai-{GENAI_VERSION}/genai_wasm_internal.js',
                   'wasm': {'file': 'wasm', 'size': len(wasm), 'sha256': hashlib.sha256(wasm).hexdigest()}},
        'model': {'id': f'{MODEL_REPO}@{MODEL_COMMIT[:12]}/{MODEL_FILE}', 'name': 'Gemma 4 E2B', 'license': 'Apache-2.0',
                  'file': 'model', 'size': size, 'part': PART, 'parts': parts},
    }
    out = root / 'js/device-llm-catalog.js'
    out.write_text(
        '// GENERATED by tools/device_llm_catalog.py. Do not edit.\n'
        '// The on-device AI (js/device-llm.js) downloads ONLY these files, through /api/device-llm, and checks every size and SHA-256.\n'
        f'// Model: {model_url}\n'
        f'// Engine: {NPM}wasm/genai_wasm_internal.wasm\n'
        'const DEVICE_LLM_CATALOG = ' + json.dumps(catalog, indent=1) + ';\n', encoding='utf-8')
    print(f'{out}: model {size} bytes in {len(parts)} parts, engine {len(wasm)} bytes')


if __name__ == '__main__':
    main()
